  var removingIndentation: Trivia {
    var resultPieces: [TriviaPiece] = []
    var isAfterNewline = false
    for piece in pieces {
      if piece.isSpaceOrTab && isAfterNewline {
        // Don’t add whitespace after a newline
        continue
